#!/usr/bin/env bash
# Runs as the deployment user. Incoming files were generated by prepare-release.py.
set -Eeuo pipefail
umask 077
SHA=${1:?full SHA required}
REGISTRY=${2:?ECR registry required}
[[ "$SHA" =~ ^[0-9a-f]{40}$ ]] || exit 2
[[ "$REGISTRY" =~ ^[0-9]{12}\.dkr\.ecr\.[a-z]{2}(-[a-z]+)+-[0-9]+\.amazonaws\.com$ ]] || exit 2
ROOT="${BEKOO_ROOT:-$HOME/bekoo}"
INCOMING="$ROOT/incoming/$SHA"
DIR="$ROOT/runtime"
mkdir -p "$DIR"
chmod 700 "$ROOT" "$DIR"
exec 8> "$ROOT/.activate.lock"
flock -x 8
for file in compose.yaml check-mysql.py deploy.sh command.env query.env infra.env; do
  [[ -f "$INCOMING/$file" ]] || { echo "Missing runtime file: $file" >&2; exit 2; }
done
# Existing topology/infra secrets are provisioned separately: do not rotate infrastructure in CD.
for file in compose.yaml infra.env; do
  if [[ -f "$DIR/$file" ]] && ! cmp -s "$DIR/$file" "$INCOMING/$file"; then
    echo "$file changed; review/apply it in a maintenance window before retrying deployment" >&2
    exit 2
  fi
done
if [[ -f "$DIR/release.env" ]]; then
  grep -Fxq "IMAGE_PREFIX=$REGISTRY" "$DIR/release.env" || { echo 'Registry differs from runtime release.env' >&2; exit 2; }
fi
BACKUP=$(mktemp -d "$ROOT/.previous.XXXXXX")
trap 'rm -rf "$BACKUP"' EXIT
for file in command.env query.env; do
  if [[ -f "$DIR/$file" ]]; then cp -p "$DIR/$file" "$BACKUP/$file"; fi
done
for file in compose.yaml check-mysql.py deploy.sh command.env query.env infra.env; do
  install -m 600 "$INCOMING/$file" "$DIR/$file"
done
if [[ ! -f "$DIR/release.env" ]]; then
  printf 'IMAGE_PREFIX=%s\nIMAGE_TAG=%s\nCOMMAND_HOST_PORT=8083\nQUERY_HOST_PORT=8084\n' "$REGISTRY" "$SHA" > "$DIR/release.env"
fi
# Keep previous app credentials available for application rollback.
export ROLLBACK_ENV_DIR="$BACKUP"
if APPS_ROOT="$ROOT" bash "$DIR/deploy.sh" runtime "$SHA"; then
  rm -rf "$INCOMING"
else
  for file in command.env query.env; do
    if [[ -f "$BACKUP/$file" ]]; then install -m 600 "$BACKUP/$file" "$DIR/$file"; fi
  done
  echo 'Deployment failed; inspect container logs and health. Previous app env restored where available.' >&2
  exit 1
fi
